CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,is_global_admin INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS apps(id TEXT PRIMARY KEY,app_id TEXT NOT NULL,name TEXT NOT NULL,directory TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_apps(user_id TEXT NOT NULL,app_id TEXT NOT NULL,is_admin INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,app_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(app_id) REFERENCES apps(id) ON DELETE CASCADE);
